package lk.medical.controller;
import lk.medical.model.*; import lk.medical.service.MedicalService; import jakarta.servlet.http.HttpSession; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes; import java.time.*;
@Controller public class WebController { private final MedicalService service; public WebController(MedicalService s){service=s;} private User current(HttpSession s){return (User)s.getAttribute("user");} private String roleHome(User u){return u==null?"redirect:/login":switch(u.getRole()){case "ADMIN"->"redirect:/admin";case "DOCTOR"->"redirect:/dashboard";default->"redirect:/dashboard";};}
 @GetMapping("/") public String home(@RequestParam(defaultValue="") String q,Model m){m.addAttribute("doctors",service.doctors(q));m.addAttribute("q",q);return "index";}
 @GetMapping("/login") public String loginPage(){return "login";} @PostMapping("/login") public String login(@RequestParam String email,@RequestParam String password,@RequestParam String role,HttpSession session,RedirectAttributes ra){User u=service.login(email,password,role);if(u==null){ra.addFlashAttribute("error","Login failed. Check your role, email and password.");return "redirect:/login";}session.setAttribute("user",u);return roleHome(u);}
 @GetMapping("/register") public String registerPage(){return "register";} @PostMapping("/register") public String register(@RequestParam String name,@RequestParam String email,@RequestParam String password,@RequestParam(defaultValue="") String phone,@RequestParam(defaultValue="") String address,RedirectAttributes ra){try{service.register(name,email,password,phone,address);ra.addFlashAttribute("success","Account created. You can now sign in.");return "redirect:/login";}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());return "redirect:/register";}}
 @GetMapping("/logout") public String logout(HttpSession s){s.invalidate();return "redirect:/";}
 @GetMapping("/dashboard") public String dashboard(HttpSession s,Model m){User u=current(s);if(u==null)return "redirect:/login";m.addAttribute("user",u);m.addAttribute("doctors",service.doctors(""));m.addAttribute("appointments",service.appointmentsFor(u));m.addAttribute("records",service.recordsFor(u));return "dashboard";}
 @PostMapping("/appointments/book") public String book(@RequestParam String doctorId,@RequestParam String date,@RequestParam String time,@RequestParam(defaultValue="") String reason,HttpSession s,RedirectAttributes ra){User u=current(s);if(u==null)return "redirect:/login";if(!"PATIENT".equals(u.getRole())){ra.addFlashAttribute("error","Only patients can book appointments.");return roleHome(u);}try{service.book(u.getId(),doctorId,LocalDate.parse(date),LocalTime.parse(time),reason);ra.addFlashAttribute("success","Appointment request saved successfully.");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/dashboard";}
 @PostMapping("/appointments/action") public String appointmentAction(@RequestParam String id,@RequestParam String action,@RequestParam(required=false) String date,@RequestParam(required=false) String time,@RequestParam(defaultValue="") String note,@RequestParam(defaultValue="") String feedback,HttpSession s,RedirectAttributes ra){User u=current(s);if(u==null)return "redirect:/login";try{service.updateAppointment(id,action,date==null||date.isBlank()?null:LocalDate.parse(date),time==null||time.isBlank()?null:LocalTime.parse(time),note,feedback,u);ra.addFlashAttribute("success","Appointment updated.");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return roleHome(u);}
 @GetMapping("/admin") public String admin(HttpSession s,Model m){User u=current(s);if(u==null)return "redirect:/login";if(!"ADMIN".equals(u.getRole()))return roleHome(u);m.addAttribute("user",u);m.addAttribute("doctors",service.doctors(""));m.addAttribute("patients",service.patients());m.addAttribute("appointments",service.appointments());return "admin";}
 @PostMapping("/admin/doctor/save") public String saveDoctor(@RequestParam(defaultValue="") String id,@RequestParam String name,@RequestParam String specialization,@RequestParam String availability,@RequestParam String room,@RequestParam double fee,@RequestParam(defaultValue="GP") String type,@RequestParam String email,@RequestParam(defaultValue="doctor123") String password,HttpSession s,RedirectAttributes ra){if(current(s)==null||!"ADMIN".equals(current(s).getRole()))return "redirect:/login";try{service.saveDoctor(id.isBlank()?"D"+java.util.UUID.randomUUID().toString().substring(0,8):id,name,specialization,availability,room,fee,type,email,password);ra.addFlashAttribute("success","Doctor saved.");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/admin";}
 @PostMapping("/admin/doctor/delete") public String deleteDoctor(@RequestParam String id,HttpSession s,RedirectAttributes ra){if(current(s)==null||!"ADMIN".equals(current(s).getRole()))return "redirect:/login";service.deleteDoctor(id);ra.addFlashAttribute("success","Doctor removed.");return "redirect:/admin";}
 @PostMapping("/admin/patient/delete") public String deletePatient(@RequestParam String id,HttpSession s,RedirectAttributes ra){if(current(s)==null||!"ADMIN".equals(current(s).getRole()))return "redirect:/login";service.deletePatient(id);ra.addFlashAttribute("success","Patient removed.");return "redirect:/admin";}
}
